export function mergeContactLabels(existing, incoming) {
  const seen = new Map();
  for (const label of [...existing, ...incoming]) {
    const trimmed = label.trim();
    if (trimmed === '') continue;
    const key = trimmed.toLowerCase();
    if (!seen.has(key)) seen.set(key, trimmed);
  }
  return [...seen.values()];
}

