});

input.new_string:
test('merges unique labels in insertion order', () => {
  assert.deepEqual(mergeContactLabels(['owner'], ['owner', 'billing']), ['owner', 'billing']);
});

test('trims whitespace from labels', () => {
  assert.deepEqual(mergeContactLabels(['  owner  '], [' billing']), ['owner', 'billing']);
});

test('discards blank labels', () => {
  assert.deepEqual(mergeContactLabels(['owner', '   '], ['', 'billing']), ['owner', 'billing']);
});

test('dedupes case-insensitively, keeping first spelling', () => {
  assert.deepEqual(mergeContactLabels(['Owner'], ['owner', 'OWNER', 'Billing']), ['Owner', 'Billing']);
});

test('does not mutate input arrays', () => {
  const existing = ['Owner', ''];
  const incoming = ['owner', 'Billing'];
  mergeContactLabels(existing, incoming);
  assert.deepEqual(existing, ['Owner', '']);
  assert.deepEqual(incoming, ['owner', 'Billing']);
});
